parameters.jsCode:
// Parse AI JSON response safely
let aiResponse;
try {
  const raw = $input.item.json.message?.content
    || $input.item.json.choices?.[0]?.message?.content
    || $input.item.json.text || '{}';
  const clean = raw.replace(/```json\n?/g, '').replace(/```/g, '').trim();
  aiResponse = JSON.parse(clean);
} catch(e) {
  aiResponse = {
    intent: 'GENERAL_QUERY',
    reply_message: 'Thank you for reaching out! Our counsellor will contact you shortly. 😊',
    new_status: 'CONTACTED',
    ai_next_action: 'Review student message and call manually.',
    ai_summary: 'AI parse failed — manual review needed.'
  };
}

const lead = $('Find Lead by Phone').item.json;
const wh = $('Student Reply Webhook').item.json;
const msg = wh.body?.message || wh.message || '';

return {
  json: {
    lead_id: lead.lead_id,
    lead_name: lead.name,
    lead_phone: lead.phone,
    student_message: msg,
    caller_name: lead.caller?.full_name || 'Our Team',
    caller_phone: lead.caller?.phone || '',
    course_name: lead.course?.name || 'our courses',
    course_fee: lead.course?.fee || null,
    course_duration: lead.course?.duration || null,
    intent: aiResponse.intent,
    reply_message: aiResponse.reply_message,
    new_status: aiResponse.new_status,
    ai_next_action: aiResponse.ai_next_action,
    ai_summary: aiResponse.ai_summary,
    is_hot: ['ADMISSION_INTEREST', 'FEE_ENQUIRY'].includes(aiResponse.intent)
  }
};

